def _seed_dev_user(db_factory, *, portal: Portal, role: AdminRole | None = None):
    db = db_factory()
    user = User(
        id=uuid.uuid4(),
        firebase_uid="dev-user",
        email="dev@example.com",
        portal=portal,
        status=AccountStatus.ACTIVE,
    )
    db.add(user)
    db.flush()
    if portal == Portal.ADMIN:
        db.add(AdminProfile(user_id=user.id, role=role or AdminRole.RM, name="Dev Admin"))
    else:
        db.add(ClientProfile(user_id=user.id, name="Dev Client"))
    db.commit()
    db.close()


def _seed_model(db_factory):
    from decimal import Decimal

    from app.models.pc import Model

    db = db_factory()
    model = Model(
        id=uuid.uuid4(),
        name="Alpha Model",
        model_size=Decimal("1000000"),
        mgmt_fee=Decimal("0.02"),
        incentive_fee=Decimal("0.2"),
    )
    db.add(model)
    db.commit()
    model_id = model.id
    db.close()
    return model_id


def _start_onboarding(http, model_id, *, email="cathy@example.com"):
    body = {
        "client_name": "Cathy Client",
        "email": email,
        "primary_phone": "1",
        "address": "A",
        "country_of_residence": "HK",
        "id_type": "Passport",
        "id_number": "P1",
        "ibhk_account": "IB1",
        "sw_account": "SW1",
        "model_id": str(model_id),
        "units": "5",
        "mgmt_fee": "0.02",
        "incentive_fee": "0.2",
        "initial_cash_deposit": "5000000",  # NEW (014 BE-8) -- exactly the floor for units=5 * model_size=1_000_000
    }
    return http.post("/api/rm/onboardings", json=body)


# --- Positive: each of the 14 routes reaches its handler and returns its documented status ---


def test_rm_start_onboarding_returns_201(admin_client):
    http, db_factory, *_ = admin_client
    model_id = _seed_model(db_factory)
    resp = _start_onboarding(http, model_id)
    assert resp.status_code == 201, resp.text
    body = resp.json()
    assert body["status"] == "initial"
    assert len(body["documents"]) == 7


def test_rm_get_board_returns_200_with_four_buckets(admin_client):
    http, db_factory, *_ = admin_client
    model_id = _seed_model(db_factory)
    _start_onboarding(http, model_id)
    resp = http.get("/api/rm/onboardings")
    assert resp.status_code == 200, resp.text
    body = resp.json()
    for key in ("initial", "reviewing", "pending_review", "active"):
        assert key in body
    assert len(body["initial"]) == 1


