def _submitted_cycle(admin_client):
    http, db_factory, _stub, set_role = admin_client
    model_id = _seed_model(db_factory)
    started = _start_onboarding(http, model_id).json()
    _upload_all_docs(http, started["id"])
    http.post(f"/api/rm/onboardings/{started['id']}/submit")
    set_role(AdminRole.COMPLIANCE)
    return started


