# --- Client route scoping: never trusts a client-supplied user_id ------------------


def test_client_subscriptions_route_takes_no_user_id_query_param(client_portal_client):
    """Client routes are always own-user_id-scoped -- a query param would be
    silently ignored by the route signature (no such param exists), never
    honoured to view another client's data."""
    http, _db_factory, stub_user = client_portal_client
    other_id = uuid.uuid4()
    resp = http.get(f"/api/client/subscriptions?user_id={other_id}")
    assert resp.status_code == 200  # extra unknown query params are simply ignored
    # still returns the AUTHENTICATED user's own (empty) data, not other_id's
    assert resp.json() == []


# --- Invariant: exactly 19 onboarding routes registered -----------------------------
# (was 16 per 013; 014 BE-2/BE-3/BE-7 add +3 matching this filter's segments --
# BE-7's /rm/clients/{client_id}/events and BE-9's /rm/subscriptions* routes don't
# match any of this filter's five segments, so they aren't counted here.)


def test_exactly_nineteen_onboarding_routes_are_registered():
    paths = app.openapi()["paths"]
    onboarding_paths = {
        p: methods
        for p, methods in paths.items()
        if any(
            seg in p
            for seg in (
                "/rm/onboardings",
                "/compliance/onboardings",
                "/pc/allotments",
                "/client/subscriptions",
                "/client/events",
            )
        )
    }
    total_routes = sum(len(methods) for methods in onboarding_paths.values())
    assert total_routes == 19


